"use strict";
try{document.body.classList.toggle("comm-large",localStorage.getItem("rebirth_large_type")==="on")}catch{}
(async()=>{const message=document.querySelector('#admin-message'),list=document.querySelector('#admin-users');let user;async function load(){const r=await fetch('/api/admin/users',{headers:{'X-Rebirth-Account':user.id}});const data=await r.json();if(!r.ok)throw Error(data.error);list.replaceChildren();for(const u of data.users){const card=document.createElement('section'),name=document.createElement('h2'),status=document.createElement('p');name.textContent=u.name;status.textContent=(u.role==='admin'?'管理员':'成员')+' · '+(u.disabled?'已停用':'可使用');card.append(name,status);if(u.role!=='admin'){const button=document.createElement('button');button.textContent=u.disabled?'重新启用':'停用账号';button.onclick=async()=>{if(!u.disabled&&!confirm('停用 '+u.name+'？对方会退出登录，记录会保留。'))return;button.disabled=true;try{const r=await fetch('/api/admin/status',{method:'POST',headers:{'Content-Type':'application/json','X-Rebirth-Account':user.id},body:JSON.stringify({id:u.id,disabled:!u.disabled})});const data=await r.json();if(!r.ok)throw Error(data.error);await load()}catch(e){message.textContent=e.message;button.disabled=false}};card.append(button)}list.append(card)}message.textContent='共 '+data.users.length+' 个账号'}try{const r=await fetch('/api/session');if(!r.ok){location.assign('/login');return}user=(await r.json()).user;await load()}catch(e){message.textContent=e.message||'读取失败，请刷新重试'}})();